import{r as n,j as e,N as s,F as d}from"./index-CH6sutyX.js";const c=[{type:"p",text:"This Privacy Policy explains how Coetzee Tech, Inc., a Delaware corporation doing business as SafeRides (“SafeRides,” “we,” “us,” or “our”), collects, uses, shares, and protects information when you use our services in the United States (the “Services”), including our mobile applications, websites, and related features such as ride requests, student and driver onboarding, scheduling, safety tools, communications, and customer support."},{type:"p",text:"This Privacy Policy is incorporated into and forms part of the SafeRides Terms of Service. Capitalized terms used but not defined in this Privacy Policy have the meaning given to them in the Terms of Service. By creating an account or using the Services, you acknowledge that you have read and understand this Privacy Policy."}],l=["Who We Are","Scope of This Policy","Key Definitions","Information We Collect","How We Use Information","SMS/Text Messaging","How We Share Information","Data Retention","Security","Your Controls and Choices","Cookies, Analytics, and Advertising","Children’s Privacy (18+ Service)","US State Privacy Rights","Do Not Sell or Share; Targeted Advertising Opt-Out","Changes to This Privacy Policy","How to Contact Us"],p={heading:"6. SMS/Text Messaging",blocks:[{type:"p",text:"If you provide a mobile phone number, SafeRides may send you SMS/text messages for two purposes only: (1) one-time verification codes used to confirm your phone number or complete sign-in/account actions, and (2) ride- and safety-related alerts tied to a Trip you have requested or are taking (such as pickup confirmations, Driver arrival, and Pickup Code/safety notices). We do not send marketing or promotional text messages."},{type:"lead",label:"No third-party marketing sharing.",text:"We do not sell, rent, or share your mobile phone number with third parties for their own marketing or promotional purposes. Text messaging originator opt-in data and consent are never shared with any third party for marketing purposes."},{type:"lead",label:"Message frequency.",text:"Message frequency varies based on your account and ride activity — for example, you may receive one message for a verification code, and additional messages only around trips you actually request or take. You will not receive recurring marketing texts."},{type:"lead",label:"Message and data rates.",text:"Message and data rates may apply, depending on your mobile carrier and plan."},{type:"lead",label:"Opt-out and help.",text:"You can opt out of ride/safety SMS alerts at any time by replying STOP to any message, or by updating your notification preferences in the App; reply HELP for assistance, or contact saferideshelp@gmail.com. Opting out of SMS does not affect in-app notifications or your ability to use the Services. Note that verification codes are required to complete certain security actions (such as sign-in) and cannot be opted out of while still completing that action."},{type:"p",text:"SMS vendors we use to deliver these messages act as our service providers and are contractually restricted to using your phone number only to deliver messages on our behalf — not for their own marketing purposes. See Section 7(B) below for more on our service providers generally."}]},u=[{heading:"1. Who We Are",blocks:[{type:"lead",label:"Company:",text:"Coetzee Tech, Inc. (d/b/a SafeRides™), a Delaware corporation."},{type:"lead",label:"Mailing Address:",text:"214 S Gregg Street, Columbia, SC 29205, United States."},{type:"lead",label:"Privacy Contact:",text:"saferideshelp@gmail.com."},{type:"p",text:"SafeRides operates a campus-focused technology platform that connects verified student Riders with independent Drivers. This Privacy Policy describes our information practices for that platform and the related Services."}]},{heading:"2. Scope of This Policy",blocks:[{type:"p",text:"This Privacy Policy applies to information we collect from and about:"},{type:"ul",items:["Riders who request or take rides through the Services;","Drivers who apply, are onboarded, and provide rides through the Services;","Visitors to our websites and support channels; and","Users of related features, such as scheduled rides, referral programs, promotions, and student-organization features."]},{type:"lead",label:"United States only.",text:"The Services covered by this Privacy Policy are intended for use in the United States. We do not target or market these Services to users outside the United States under this Privacy Policy."}]},{heading:"3. Key Definitions",blocks:[{type:"dl",items:[{term:"Personal Information (or Personal Data).",def:"Information that identifies, relates to, describes, or could reasonably be linked, directly or indirectly, with you."},{term:"Sensitive Personal Information (or Sensitive Data).",def:"Certain higher-risk categories of Personal Information that may receive additional protections under applicable law, such as precise geolocation, government identification numbers, account login credentials, and certain safety-related information."},{term:"Processing.",def:"Any operation performed on Personal Information, including collection, use, storage, organization, disclosure, and deletion."}]}]},{heading:"4. Information We Collect",blocks:[{type:"p",text:"We collect information in three ways: (A) information you provide to us, (B) information we collect automatically when you use the Services, and (C) information we receive from third parties."},{type:"h3",text:"A. Information You Provide"},{type:"lead",label:"Account and profile information.",text:"When you register and maintain an account, we may collect your name; email address and/or phone number; profile photo (optional for Riders, and generally required for Drivers); password and authentication details; and your university or school email address or other verification signals used to confirm your eligibility for our campus-based community. You may also provide preferred settings, such as accessibility needs and ride or safety preferences."},{type:"lead",label:"Rider information.",text:"We may collect your pickup and drop-off locations (including saved or suggested places you choose); ride requests and ride preferences; scheduled ride details (destination, date, and time); payment method details (we typically receive tokens and limited card details from our payment processors rather than full card numbers); promotional, discount, and referral codes; a verification or Pickup Code you set or use; and your communications with Drivers and with our support team."},{type:"lead",label:"Driver information.",text:"In addition to the above, Drivers may provide a driver’s license and other government-issued identification; vehicle information (such as make, model, year, license plate, insurance details, and inspection information where required); background-check information, subject to vendor processes and applicable law; banking or payout details, typically handled through a payment-processor onboarding flow; tax-related information where required for payouts; and availability and ride-type preferences."},{type:"lead",label:"Safety and support information.",text:"We may collect incident reports (safety issues, complaints, disputes, and lost items); evidence you provide, such as messages, screenshots, and photos; emergency contact information if you choose to add it; and details of your interactions with customer support. If you contact support by phone or in-app and call recording is enabled, we will notify you where required by law."},{type:"h3",text:"B. Information We Collect Automatically"},{type:"lead",label:"Location information.",text:"With your permission, we may collect precise geolocation from your device to enable pickup, routing, estimated arrival times, geofencing, safety features, and fraud prevention. We may collect trip route details during a ride (such as start location, route path, and drop-off), and Driver location while a Driver is online or available and during trips. You can control location permissions in your device settings, but some features will not work without location access."},{type:"lead",label:"Usage and device data.",text:"We may collect your device model and operating-system version; app version; device identifiers (such as an advertising identifier where permitted and a push-notification token); IP address and approximate location derived from it; crash, performance, and diagnostic logs; and app-interaction data such as screens viewed, taps, and session duration."},{type:"lead",label:"Communications and content.",text:"Where in-app messaging exists, we may collect messages sent through the App, the time and date of communications, and delivery or read receipts where enabled."},{type:"lead",label:"Cookies and similar technologies (web).",text:"When you use our websites, we may use cookies, pixels, and similar tools to keep you logged in, remember preferences, measure performance, and support marketing, as described in Section 11."},{type:"h3",text:"C. Information We Receive From Third Parties"},{type:"p",text:"We may receive information about you from:"},{type:"ul",items:["identity-verification and background-check providers (for Drivers);","payment processors (for example, to confirm successful payments, chargebacks, and payout-onboarding status);","mapping and navigation providers (for geocoding, directions, and route estimates);","analytics and attribution providers (to understand performance and install sources);","marketing partners, where permitted;","insurers, claims administrators, investigators, and safety partners, in connection with an incident or claim; and","law enforcement or government authorities, where legally required or permitted."]}]},{heading:"5. How We Use Information",blocks:[{type:"p",text:"We use information to operate, improve, and protect the Services. Our purposes include the following."},{type:"h3",text:"A. Provide the Services"},{type:"ul",items:["create and manage accounts, and verify eligibility for our campus community;","enable ride requests, match Riders with Drivers, and provide routing and estimated arrival times;","transmit pickup and destination locations and track rides in progress;","calculate fares, process payments, and facilitate Driver payouts;","provide receipts and trip history;","operate scheduled rides, promotions, and referral programs;","deliver service communications and respond to your requests;","collect and display feedback and ratings; and","test, debug, monitor performance and security, and develop new features."]},{type:"h3",text:"B. Safety, Trust, and Security"},{type:"ul",items:["authenticate and verify Users, including Driver onboarding, and prevent fraudulent registrations;","conduct background checks where permitted or required;","verify that Drivers’ vehicles meet applicable safety, legal, and platform requirements;","verify that Users carry the insurance they are required to maintain;","support safety features, including identity and Pickup Code verification flows and emergency support;","detect, investigate, and prevent fraud, abuse, and unsafe activity, and enforce our policies; and","investigate accidents, incidents, disputes, and any related claims, and remove Users who violate our policies."]},{type:"h3",text:"C. Improve and Personalize"},{type:"p",text:"We use information to fix bugs and optimize performance, understand feature usage and improve the experience, and personalize content such as suggestions and saved preferences."},{type:"h3",text:"D. Communications"},{type:"p",text:"We use information to send service messages (such as trip updates, confirmations, and security alerts), respond to support tickets, and, where permitted, send marketing messages that you can opt out of."},{type:"h3",text:"E. Legal and Compliance"},{type:"p",text:"We use information to meet legal obligations, resolve disputes, maintain business records, and protect the rights, safety, and property of SafeRides, our Users, and others."}]},p,{heading:"7. How We Share Information",blocks:[{type:"p",text:"We do not sell your Personal Information in the way most people understand the word “sell” (that is, handing your data to unrelated third parties for money). However, some US state laws define “sale” and “sharing” broadly, including certain targeted-advertising activities. We address opt-outs in Sections 13 and 14. We may share information as described below."},{type:"h3",text:"A. Between Riders and Drivers (Core Function)"},{type:"p",text:"To complete a Trip, we share information between the Rider and the Driver, which may include:"},{type:"ul",items:["the Rider’s first name and profile photo (if provided);","pickup and drop-off locations (which may be approximate until pickup, depending on the feature);","trip status, estimated arrival time, and route guidance;","the Driver’s name, profile photo, rating, real-time location, and vehicle make, model, color, and license plate; and","safety-related information necessary to complete the ride, including the Pickup Code verification flow."]},{type:"p",text:"Feedback and ratings submitted after a Trip may be shared with the other party, but the identity of the submitting User will generally be redacted."},{type:"lead",label:"Lost items.",text:"If you believe you left a personal item during a Trip, you can contact us through the App with a description of the item, and we may contact the relevant Driver and attempt to coordinate its return as a courtesy."},{type:"h3",text:"B. Service Providers (Vendors and Processors)"},{type:"p",text:"We use vendors to help run SafeRides, such as cloud hosting and databases; payment processing and payout onboarding; SMS and email delivery; customer-support tools; analytics; mapping and geocoding; and identity-verification and background-check providers (for Drivers). These vendors may process information only on our instructions or as otherwise permitted by law and contract."},{type:"h3",text:"C. Student Organizations and Campus Partners"},{type:"p",text:"If you use features that integrate with a student organization (such as a fraternity, sorority, club, or other campus group), we may share limited information with that organization as necessary to provide the feature you have chosen to use, as described or enabled at the point of use."},{type:"h3",text:"D. Affiliates and Business Transfers"},{type:"p",text:"If SafeRides is involved in a merger, acquisition, financing, reorganization, or sale of assets, information may be transferred as part of that transaction, subject to applicable law."},{type:"h3",text:"E. Legal, Safety, and Enforcement"},{type:"p",text:"We may disclose information to law enforcement, courts, regulators, or government agencies when required or permitted by law (for example, pursuant to court orders, government investigations, or subpoenas); to third parties to protect rights, safety, and security, including for fraud prevention and incident response; and to insurers, claims administrators, or investigators when relevant to an accident, incident, dispute, or claim involving the Services, including a User’s own insurer or a third party’s insurer."},{type:"h3",text:"F. With Your Consent"},{type:"p",text:"If you choose to connect the Services to a third-party service or otherwise ask us to share your information, we will do so with your permission."}]},{heading:"8. Data Retention",blocks:[{type:"p",text:"We retain information only as long as necessary for the purposes described in this Privacy Policy, including to provide the Services, meet legal and accounting obligations, resolve disputes, and enforce our policies and prevent fraud. Retention periods depend on the type of data:"},{type:"ul",items:["Account data is generally retained while your account is active;","Trip and payment records may be retained longer for legal, tax, and accounting purposes;","Safety and incident records may be retained longer where needed to protect Users and the platform; and","When you request deletion, we may still retain certain information to comply with law or for legitimate business needs, such as resolving disputes or claims."]},{type:"p",text:"In some cases, deleting certain information may require us to deactivate your account, because we cannot provide the Services without it."}]},{heading:"9. Security",blocks:[{type:"p",text:"We use administrative, technical, and physical safeguards designed to protect information. No system is perfectly secure, and we cannot guarantee absolute security. You are responsible for keeping your login credentials confidential and for using device-level security features. If you believe your account has been compromised, contact us at saferideshelp@gmail.com."}]},{heading:"10. Your Controls and Choices",blocks:[{type:"lead",label:"Account information.",text:"You can review and update certain profile information in the App."},{type:"lead",label:"Location controls.",text:"You can control location permissions at the device level. If you deny location access, features such as ride matching, routing, and geofencing may not work."},{type:"lead",label:"Marketing preferences.",text:"You can opt out of marketing emails using the unsubscribe link. Under the federal CAN-SPAM Act, businesses must honor opt-out requests within ten (10) business days."},{type:"lead",label:"Push notifications.",text:"You can disable push notifications in your device settings, although some notifications are important for trips and safety."}]},{heading:"11. Cookies, Analytics, and Advertising",blocks:[{type:"p",text:"On our websites and in our App, we may use cookies, software development kits (SDKs), pixels, and similar technologies to keep you logged in, remember preferences, measure traffic and performance, understand user journeys, and support marketing and attribution."},{type:"lead",label:"Targeted advertising and “sale”/“share” concepts.",text:"Some state laws treat certain advertising-technology disclosures as a “sale” or “sharing” of Personal Information for targeted advertising. If we engage in targeted advertising, you may have the right to opt out, as described in Sections 13 and 14."},{type:"lead",label:"Universal opt-out signals.",text:"Certain states require businesses to recognize browser-based opt-out signals, such as the Global Privacy Control (GPC), for opt-outs of sale or targeted advertising. We aim to honor legally recognized opt-out preference signals where required."}]},{heading:"12. Children’s Privacy (18+ Service)",blocks:[{type:"p",text:"The Services are intended only for adults who are at least eighteen (18) years old. We do not direct the Services to, and do not knowingly collect Personal Information from, anyone under 18. Consistent with the Children’s Online Privacy Protection Act (“COPPA”), we also do not knowingly collect Personal Information from children under 13."},{type:"p",text:"If you believe a person under 18 has provided us Personal Information, please contact us at saferideshelp@gmail.com and we will take appropriate steps to delete it and terminate the associated account."}]},{heading:"13. US State Privacy Rights",blocks:[{type:"p",text:"US privacy laws vary by state and continue to evolve. This section summarizes rights that may be available depending on your state of residence."},{type:"lead",label:"How to exercise your rights.",text:"Email saferideshelp@gmail.com with the subject line “Privacy Request” and include your full name; the email or phone number associated with your account; your state of residence; and the type of request (Access, Delete, Correct, Portability, Opt Out, or Appeal). We may need to verify your identity before fulfilling a request, to protect you against fraud. If you use an authorized agent where permitted, we may require proof of authorization and may still verify you directly."},{type:"h3",text:"California (CCPA, as amended by the CPRA)"},{type:"p",text:"California residents may have the right to know and access the categories and specific pieces of Personal Information we collect; to delete Personal Information, subject to exceptions; to correct inaccurate Personal Information; to opt out of the “sale” or “sharing” of Personal Information for cross-context behavioral advertising; to limit the use and disclosure of Sensitive Personal Information where applicable; and to be free from discrimination for exercising these rights. California requires businesses to respond to certain verified requests within 45 days, with a possible extension."},{type:"lead",label:"Notice at collection (high-level summary).",text:"Categories of Personal Information we collect include identifiers; commercial information (such as trip and payment history); geolocation; internet and device information; audiovisual information (if provided); inferences; and, for Drivers, Sensitive Data such as precise geolocation and government identification numbers. We collect this information for the purposes described in Section 5, including providing rideshare services, processing payments and payouts, supporting safety, preventing fraud, providing customer support, improving the Services, and, where permitted, marketing. We disclose information as described in Section 7, including to service providers, between Riders and Drivers to complete Trips, to payment processors and mapping providers, for legal and safety purposes, and in business transfers."},{type:"h3",text:"Other State Privacy Laws"},{type:"p",text:"Depending on your state of residence, you may have rights under a comprehensive state privacy law. The following states have enacted such laws, which generally provide rights to access, delete, correct, and obtain a portable copy of Personal Information, and to opt out of targeted advertising, the sale of Personal Information, and certain profiling (the specific rights and exceptions vary by state):"},{type:"ul",items:["Virginia (Consumer Data Protection Act);","Colorado (Colorado Privacy Act);","Connecticut (Connecticut Data Privacy Act);","Utah (Utah Consumer Privacy Act — more limited than some states);","Texas (Texas Data Privacy and Security Act);","Oregon (Oregon Consumer Privacy Act);","Montana (Montana Consumer Data Privacy Act);","Tennessee (Tennessee Information Protection Act);","Iowa (Iowa Consumer Data Protection Act);","Delaware (Delaware Personal Data Privacy Act, including recognition of universal opt-out signals);","New Jersey (New Jersey Data Privacy Act);","New Hampshire (New Hampshire Data Privacy Act);","Florida (Florida Digital Bill of Rights);","Indiana (Indiana Consumer Data Protection Act);","Kentucky (Kentucky Consumer Data Protection Act); and","Rhode Island (Rhode Island Data Transparency and Privacy Protection Act)."]},{type:"h3",text:"Summary of Rights and Appeals"},{type:"p",text:"Depending on your state, you may have the right to: confirm whether we process your Personal Information and access it; request deletion, subject to exceptions; correct inaccuracies; obtain a portable copy; opt out of targeted advertising, the sale of Personal Information, and certain profiling; and appeal a denial where required. If we deny a request, we will explain why, as required, and provide an appeal method where applicable."}]},{heading:"14. Do Not Sell or Share; Targeted Advertising Opt-Out",blocks:[{type:"p",text:"If applicable state law gives you the right to opt out of targeted advertising, the “sale” of Personal Information, or the “sharing” of Personal Information for cross-context behavioral advertising (California terminology), you may submit an opt-out request by emailing saferideshelp@gmail.com. We also aim to honor legally recognized opt-out preference signals, such as the Global Privacy Control, where required."}]},{heading:"15. Changes to This Privacy Policy",blocks:[{type:"p",text:"We may update this Privacy Policy from time to time. If we make material changes, we will provide notice through the App, our website, or by other means as required by law. The “Last Updated” date at the top of this Privacy Policy indicates when it was most recently revised."}]},{heading:"16. How to Contact Us",blocks:[{type:"p",text:"For questions, complaints, or privacy requests, contact us at:"},{type:"lead",label:"Email:",text:"saferideshelp@gmail.com"},{type:"lead",label:"Mail:",text:"Coetzee Tech, Inc. (d/b/a SafeRides™), 214 S Gregg Street, Columbia, SC 29205, United States"},{type:"p",strong:!0,text:"By using the SafeRides Services, you acknowledge that you have read and understand this Privacy Policy."}]}];function r(t,a){switch(t.type){case"h3":return e.jsx("h3",{className:"text-lg font-semibold text-[#1A1A1A] mt-6 mb-2",children:t.text},a);case"p":return e.jsx("p",{className:`text-[#1A1A1A] mb-3${t.strong?" font-semibold":""}`,children:t.text},a);case"lead":return e.jsxs("p",{className:"text-[#1A1A1A] mb-3",children:[e.jsx("strong",{children:t.label})," ",t.text]},a);case"ul":return e.jsx("ul",{className:"list-disc list-inside space-y-1 text-[#1A1A1A] mb-3",children:t.items.map((i,o)=>e.jsx("li",{children:i},o))},a);case"dl":return e.jsx("div",{className:"space-y-2 mb-3",children:t.items.map((i,o)=>e.jsxs("p",{className:"text-[#1A1A1A]",children:[e.jsx("strong",{children:i.term})," ",i.def]},o))},a);default:return null}}const h=()=>(n.useEffect(()=>{document.title="Privacy Policy - SafeRides"},[]),e.jsxs("div",{className:"min-h-screen bg-white",children:[e.jsx(s,{}),e.jsx("main",{children:e.jsxs("div",{className:"max-w-4xl mx-auto px-4 sm:px-6 lg:px-8 py-12 lg:py-16",children:[e.jsxs("header",{className:"mb-8",children:[e.jsx("h1",{className:"text-2xl font-bold text-[#1A1A1A]",children:"SafeRides™ Privacy Policy"}),e.jsx("p",{className:"text-sm text-[#6B7280] mt-2",children:"United States • Coetzee Tech, Inc. (d/b/a SafeRides) • Effective Date: June 1, 2026 • Last Updated: June 1, 2026"})]}),e.jsxs("div",{className:"space-y-6 text-sm leading-relaxed",children:[c.map((t,a)=>r(t,a)),e.jsxs("section",{children:[e.jsx("h2",{className:"text-xl font-semibold text-[#1A1A1A] mt-8 mb-3",children:"Table of Contents"}),e.jsx("ol",{className:"list-decimal list-inside space-y-1 text-[#1A1A1A]",children:l.map((t,a)=>e.jsx("li",{children:t},a))})]}),u.map((t,a)=>e.jsxs("section",{children:[e.jsx("h2",{className:"text-xl font-semibold text-[#1A1A1A] mt-8 mb-3",children:t.heading}),t.blocks.map((i,o)=>r(i,o))]},a))]})]})}),e.jsx(d,{})]}));export{h as default};
